+
+    public FTypeGenericArrow(String name, Source source) {
+        super(name);
+        this.source = source;
+    }
+
+    @Override
+    public boolean subtypeOf(FType other) {
+        if (commonSubtypeOf(other)) return true;
+        return other instanceof FTypeArrow && source.receivedAt((FTypeArrow) other);
+    }
